class Solution {
public:
    long long maximizeSumOfWeights(vector<vector<int>>& edges, int k) {
        int n = edges.size() + 1;
        vector<vector<pair<int, int>>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }

        auto dfs = [&](auto& self, int u, int p) -> pair<long long, long long> {
            long long baseSum = 0;
            vector<long long> gains;
            for (const auto& edge : adj[u]) {
                int v = edge.first;
                int w = edge.second;
                if (v == p) continue;
                auto [v0, v1] = self(self, v, u);
                baseSum += v0;
                long long gain = w + v1 - v0;
                if (gain > 0) gains.push_back(gain);
            }
            sort(gains.rbegin(), gains.rend());

            long long res0 = baseSum;
            for (int i = 0; i < min((int)gains.size(), k); ++i) res0 += gains[i];

            long long res1 = baseSum;
            for (int i = 0; i < min((int)gains.size(), max(0, k - 1)); ++i) res1 += gains[i];

            return {res0, res1};
        };

        return dfs(dfs, 0, -1).first;
    }
};

class Solution {
    public long maximizeSumOfWeights(int[][] edges, int k) {
        int n = edges.length + 1;
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; ++i) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(new int[]{e[1], e[2]});
            adj[e[1]].add(new int[]{e[0], e[2]});
        }
        return dfs(0, -1, adj, k)[0];
    }

    private long[] dfs(int u, int p, List<int[]>[] adj, int k) {
        long baseSum = 0;
        List<Long> gains = new ArrayList<>();
        for (int[] edge : adj[u]) {
            int v = edge[0];
            int w = edge[1];
            if (v == p) continue;
            long[] vRes = dfs(v, u, adj, k);
            baseSum += vRes[0];
            long gain = w + vRes[1] - vRes[0];
            if (gain > 0) gains.add(gain);
        }
        Collections.sort(gains, Collections.reverseOrder());

        long res0 = baseSum;
        for (int i = 0; i < Math.min(gains.size(), k); ++i) res0 += gains.get(i);

        long res1 = baseSum;
        for (int i = 0; i < Math.min(gains.size(), Math.max(0, k - 1)); ++i) res1 += gains.get(i);

        return new long[]{res0, res1};
    }
}

var maximizeSumOfWeights = function(edges, k) {
    const n = edges.length + 1;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }

    const dfs = (u, p) => {
        let baseSum = 0;
        const gains = [];
        for (const [v, w] of adj[u]) {
            if (v === p) continue;
            const [v0, v1] = dfs(v, u);
            baseSum += v0;
            const gain = w + v1 - v0;
            if (gain > 0) gains.push(gain);
        }
        gains.sort((a, b) => b - a);

        let res0 = baseSum;
        for (let i = 0; i < Math.min(gains.length, k); i++) res0 += gains[i];

        let res1 = baseSum;
        for (let i = 0; i < Math.min(gains.length, Math.max(0, k - 1)); i++) res1 += gains[i];

        return [res0, res1];
    };

    return dfs(0, -1)[0];
};
